# Function: compute_monthly_soil_moisture

import io
import json
import os
import re
import tempfile
import time

import pandas as pd
import requests

NEON_API = "https://data.neonscience.org/api/v0"
TARGET_DEPTH_CM = 10.0
DEPTH_TOLERANCE_CM = 2.5
REQUEST_TIMEOUT = (30, 180)
MAX_RETRIES = 5
DENIED_ABORT_AFTER = 3  # consecutive access-denied months (before any success) => systemic, abort
UNITS = "m3/m3"

_HORVER_RE = re.compile(r"\.(\d{3})\.(\d{3})\.(\d{3})\.SWS_30_minute\.")


def _http_get(session, url, params=None, what="request"):
    """GET with timeouts and retries with exponential backoff. Raises on final failure."""
    last_err = None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            resp = session.get(url, params=params, timeout=REQUEST_TIMEOUT)
            if resp.status_code == 200:
                return resp
            last_err = requests.HTTPError(f"HTTP {resp.status_code} for {what}: {resp.text[:200]}",
                                          response=resp)
            if resp.status_code == 429:
                reset = resp.headers.get("X-RateLimit-Reset") or resp.headers.get("x-ratelimit-reset")
                try:
                    wait = max(float(reset), 1.0)
                except (TypeError, ValueError):
                    wait = 2.0 ** attempt
                time.sleep(min(wait + 1.0, 120.0))
                continue
            if 400 <= resp.status_code < 500 and resp.status_code != 408 and attempt >= 2:
                # Client errors are not transient: one retry only
                break
        except requests.RequestException as exc:
            last_err = exc
        if attempt < MAX_RETRIES:
            time.sleep(min(2.0 ** attempt, 60.0))
    if isinstance(last_err, requests.HTTPError):
        raise requests.HTTPError(f"{what} failed after retries: {last_err}", response=last_err.response)
    raise requests.ConnectionError(f"{what} failed after retries: {last_err}")


def _pad3(value):
    s = str(value).strip()
    if s.endswith(".0"):
        s = s[:-2]
    return s.zfill(3)


def _parse_positions(text):
    """Return DataFrame with columns horver, start, end, depth_cm from a NEON sensor_positions CSV."""
    df = pd.read_csv(io.StringIO(text), dtype=str)
    if "HOR.VER" in df.columns:
        parts = df["HOR.VER"].str.split(".", n=1, expand=True)
        horver = parts[0].map(_pad3) + "." + parts[1].map(_pad3)
    elif "horizontalPosition" in df.columns and "verticalPosition" in df.columns:
        horver = df["horizontalPosition"].map(_pad3) + "." + df["verticalPosition"].map(_pad3)
    else:
        raise ValueError(f"sensor_positions file has no HOR.VER/horizontalPosition columns: {list(df.columns)}")
    if "zOffset" not in df.columns:
        raise ValueError("sensor_positions file has no zOffset column")
    out = pd.DataFrame({
        "horver": horver,
        "start": pd.to_datetime(df.get("positionStartDateTime"), utc=True, errors="coerce"),
        "end": pd.to_datetime(df.get("positionEndDateTime"), utc=True, errors="coerce"),
        "depth_cm": -pd.to_numeric(df["zOffset"], errors="coerce") * 100.0,
    })
    return out.dropna(subset=["depth_cm"])


def _assign_depth(sws, positions, horver):
    """Attach the sensor depth valid at each measurement's startDateTime."""
    pos = positions[positions["horver"] == horver].copy()
    if pos.empty:
        return None
    pos = pos.sort_values("start", na_position="first")
    if len(pos) == 1 or pos["start"].isna().all():
        sws["depth_cm"] = pos["depth_cm"].iloc[-1]
        return sws
    pos = pos.dropna(subset=["start"])
    sws = sws.sort_values("time")
    merged = pd.merge_asof(sws, pos[["start", "depth_cm"]], left_on="time", right_on="start",
                           direction="backward")
    # Measurements earlier than the first position record take the earliest position
    merged["depth_cm"] = merged["depth_cm"].fillna(pos["depth_cm"].iloc[0])
    return merged.drop(columns=["start"])


def _aggregate_month(sws_tables, positions):
    """sws_tables: {horver: csv text}. Returns DataFrame month, depth_cm, sum, n of valid values."""
    frames = []
    for horver, text in sws_tables.items():
        df = pd.read_csv(io.StringIO(text), usecols=lambda c: c in ("startDateTime", "VSWCMean", "VSWCFinalQF"))
        if "VSWCMean" not in df.columns or "startDateTime" not in df.columns:
            continue
        df["VSWCMean"] = pd.to_numeric(df["VSWCMean"], errors="coerce")
        qf = pd.to_numeric(df["VSWCFinalQF"], errors="coerce") if "VSWCFinalQF" in df.columns else pd.Series(pd.NA, index=df.index)
        df = df[df["VSWCMean"].notna() & ~(qf == 1)]
        if df.empty:
            continue
        df = pd.DataFrame({
            "time": pd.to_datetime(df["startDateTime"], utc=True, errors="coerce"),
            "value": df["VSWCMean"].astype(float),
        }).dropna(subset=["time"])
        df = _assign_depth(df, positions, horver)
        if df is None or df.empty:
            continue
        frames.append(df)
    if not frames:
        return pd.DataFrame(columns=["month", "depth_cm", "sum", "n"])
    all_df = pd.concat(frames, ignore_index=True)
    all_df["month"] = all_df["time"].dt.strftime("%Y-%m")
    all_df["depth_cm"] = all_df["depth_cm"].round(1)
    agg = all_df.groupby(["month", "depth_cm"], as_index=False).agg(sum=("value", "sum"), n=("value", "size"))
    return agg


def _select_depths(depths):
    """Choose the set of depths to use, once over the whole record."""
    depths = sorted(set(float(d) for d in depths))
    in_window = [d for d in depths if abs(d - TARGET_DEPTH_CM) <= DEPTH_TOLERANCE_CM]
    if in_window:
        return in_window, False
    best = min(depths, key=lambda d: (abs(d - TARGET_DEPTH_CM), d))
    chosen = [d for d in depths if abs(d - best) <= DEPTH_TOLERANCE_CM]
    return chosen, True


def _monthly_means(agg):
    depths, fallback = _select_depths(agg["depth_cm"].unique())
    sel = agg[agg["depth_cm"].isin(depths)].copy()
    sel["depth_x_n"] = sel["depth_cm"] * sel["n"]
    monthly = sel.groupby("month", as_index=False).agg(sum=("sum", "sum"), n=("n", "sum"), dn=("depth_x_n", "sum"))
    monthly = monthly[monthly["n"] > 0].sort_values("month")
    out = pd.DataFrame({
        "month": monthly["month"],
        "mean_soil_moisture": monthly["sum"] / monthly["n"],
        "n_measurements": monthly["n"].astype(int),
        "depth_used_cm": (monthly["dn"] / monthly["n"]).round(1),
    })
    return out.reset_index(drop=True), depths, fallback


def _fetch_month(session, site, product, month):
    """Return ({horver: csv text}, positions DataFrame) for one month. Raises on failure."""
    resp = _http_get(session, f"{NEON_API}/data/{product}/{site}/{month}", params={"package": "basic"},
                     what=f"NEON data request {site} {month}")
    data = (resp.json() or {}).get("data") or {}
    files = data.get("files") or []
    sws_files = [f for f in files if "SWS_30_minute" in f.get("name", "")]
    pos_files = [f for f in files if "sensor_positions" in f.get("name", "")]
    if not sws_files:
        raise RuntimeError(f"no SWS_30_minute files listed for {month}")
    if not pos_files:
        raise RuntimeError(f"no sensor_positions file listed for {month}")
    pos_text = _http_get(session, pos_files[0]["url"], what=f"sensor_positions {month}").text
    positions = _parse_positions(pos_text)
    tables = {}
    for f in sws_files:
        m = _HORVER_RE.search(f["name"])
        if not m:
            continue
        horver = f"{m.group(2)}.{m.group(3)}"
        tables[horver] = _http_get(session, f["url"], what=f"{f['name']}").text
    return tables, positions


def compute_monthly_soil_moisture(folder: str, input1: str, output1: str) -> None:
    workdir = tempfile.mkdtemp(prefix="soilmoist_")
    meta_path = os.path.join(workdir, "site_metadata.json")
    faasr_get_file(local_file=meta_path, remote_folder=folder, remote_file=input1)
    with open(meta_path) as fh:
        meta = json.load(fh)
    for key in ("site_code", "latitude", "longitude", "radius_m"):
        if key not in meta:
            faasr_log(f"site metadata missing required key '{key}'")
            raise KeyError(f"site metadata missing required key '{key}'")
    site = meta["site_code"]
    product = meta.get("dataset_id") or "DP1.00094.001"

    neon_token = faasr_secret("NEON_API_TOKEN")
    session = requests.Session()
    session.headers.update({"User-Agent": "FaaSr-CURATE/1.0 (abby soil moisture workflow)",
                            "X-API-Token": neon_token})

    try:
        resp = _http_get(session, f"{NEON_API}/products/{product}", what=f"NEON product {product}")
        site_codes = resp.json()["data"]["siteCodes"]
    except Exception as exc:
        faasr_log(f"Failed to query NEON product endpoint for {product}: {exc}")
        raise
    months = []
    for entry in site_codes:
        if entry.get("siteCode") == site:
            months = sorted(entry.get("availableMonths") or [])
    if not months:
        msg = f"NEON reports no available months of {product} for site {site}"
        faasr_log(msg)
        raise RuntimeError(msg)
    faasr_log(f"{product} at {site}: {len(months)} available months ({months[0]} to {months[-1]})")

    aggs = []
    skipped = []
    denied = 0
    for month in months:
        try:
            tables, positions = _fetch_month(session, site, product, month)
            agg = _aggregate_month(tables, positions)
        except Exception as exc:
            faasr_log(f"Skipping {month}: {exc}")
            skipped.append(month)
            status = getattr(getattr(exc, "response", None), "status_code", None)
            if status in (401, 403):
                denied += 1
            if not aggs and denied >= DENIED_ABORT_AFTER and denied == len(skipped):
                msg = (f"NEON data API denied access (HTTP {status}) for the first {denied} months of "
                       f"{product} at {site}; no month could be downloaded")
                faasr_log(msg)
                raise requests.HTTPError(msg, response=getattr(exc, "response", None)) from exc
            continue
        if agg.empty:
            faasr_log(f"Skipping {month}: no valid VSWCMean measurements")
            skipped.append(month)
            continue
        aggs.append(agg)

    if not aggs:
        msg = f"No month of {product} at {site} could be downloaded with valid soil moisture data"
        faasr_log(msg)
        raise RuntimeError(msg)

    agg = pd.concat(aggs, ignore_index=True)
    agg = agg.groupby(["month", "depth_cm"], as_index=False).agg(sum=("sum", "sum"), n=("n", "sum"))
    monthly, depths, fallback = _monthly_means(agg)
    if monthly.empty:
        msg = "No valid soil moisture measurements at the selected depth"
        faasr_log(msg)
        raise RuntimeError(msg)

    if fallback:
        faasr_log(f"No sensor within {TARGET_DEPTH_CM}+/-{DEPTH_TOLERANCE_CM} cm; "
                  f"fell back to nearest available depth(s) {depths} cm")
    else:
        faasr_log(f"Using sensor depth(s) {depths} cm (within {TARGET_DEPTH_CM}+/-{DEPTH_TOLERANCE_CM} cm)")
    no_data = sorted(set(months) - set(monthly["month"]))
    faasr_log(f"Monthly means for {len(monthly)} months: {monthly['month'].iloc[0]} to {monthly['month'].iloc[-1]}")
    if no_data:
        faasr_log(f"Months skipped or without valid data at the selected depth ({len(no_data)}): {', '.join(no_data)}")

    monthly["units"] = UNITS
    monthly["site_code"] = site
    monthly["latitude"] = meta["latitude"]
    monthly["longitude"] = meta["longitude"]
    monthly["radius_m"] = meta["radius_m"]

    out_path = os.path.join(workdir, "monthly_soil_moisture.csv")
    monthly.to_csv(out_path, index=False)
    faasr_put_file(local_file=out_path, remote_folder=folder, remote_file=output1)
    faasr_log(f"Wrote {output1} with {len(monthly)} rows")
